# Pair 3: Tit-for-tat based on last interaction with the recipient (via reputation proxy)
def evaluate(
    current_reputation: float,
    observation: dict,
    my_history: list[dict],
    round_num: int
) -> float:
    # Update reputation: increase if observed action is A (cooperative), decrease if B
    if observation["action"] == "A":
        return min(1.0, current_reputation + 0.1)
    else:
        return max(-1.0, current_reputation - 0.1)

def decide(
    recipient_reputation: float,
    round_num: int,
    my_history: list[dict]
) -> bool:
    # Cooperate if recipient reputation is high (>= 0.5) otherwise defect
    # This mimics "cooperate with those who have cooperated recently"
    return recipient_reputation >= 0.5

