    # Moderate learning rate for gradual adaptation
    learn_rate = 0.5

    # Assume 'B' is cooperative, 'A' is defection (same as original)
    if observation['action'] == 'B':
        base_target = 0.7
    else:
        base_target = -0.5

    # Slightly adjust target based on round number:
    # become more generous to cooperators and harsher on defectors as the game progresses
    if observation['action'] == 'B':
        target = base_target + 0.05 * min(1.0, round_num / 100.0)
    else:
        target = base_target - 0.05 * min(1.0, round_num / 100.0)

    target = max(-1.0, min(1.0, target))

    # Weighted average update
    new_rep = (1 - learn_rate) * current_reputation + learn_rate * target
    return max(-1.0, min(1.0, new_rep))


