        # Non-cooperative action: decrease reputation, more severely when already good
        decrement = 0.4 * (1.0 + 0.5 * abs(current_reputation))
        new_rep = current_reputation - decrement
    return max(-1.0, min(1.0, new_rep))

def decide(recipient_reputation, round_num, my_history):
    # Base threshold
    threshold = 0.4
    # Early rounds: be more cautious (higher threshold)
    if round_num < 20:
        threshold += 0.1
    # Adjust based on own cooperation history
    if len(my_history) > 0:
        coop_frac = sum(my_history) / len(my_history)
        if coop_frac > 0.75:
            # We have been too cooperative; be stricter
            threshold += 0.15
        elif coop_frac < 0.25:
